package build

import (
	"os"
	"path/filepath"
)

// LambdaNodeBootstrap is the Lambda-specific HandlerBootstrap for Node.js.
// It wraps the developer's app in the Celerity Node SDK's AWS Lambda adapter.
//
// The generated file imports from the `/handler` subpath of
// @celerity-sdk/serverless-aws rather than the package root so only the
// lean entry module is pulled in at cold start, not the full package index.
type LambdaNodeBootstrap struct {
	AppDir string
}

const (
	lambdaNodeBootstrapHandler = "__celerity_lambda_entry__.handler"
	lambdaNodeESMFilename      = "__celerity_lambda_entry__.mjs"
	lambdaNodeCJSFilename      = "__celerity_lambda_entry__.js"
)

// lambdaNodeAdapterPackage is the package the generated entry file imports. The
// app has to depend on it, since the bundle only carries what the app declares.
const lambdaNodeAdapterPackage = "@celerity-sdk/serverless-aws"

// RequiredPackage returns the adapter package the generated entry file imports.
func (n *LambdaNodeBootstrap) RequiredPackage() string {
	return lambdaNodeAdapterPackage
}

const lambdaNodeESMBootstrapContent = `// Auto-generated by Celerity CLI. Do not edit.
export { handler } from "@celerity-sdk/serverless-aws/handler";
`

const lambdaNodeCJSBootstrapContent = `// Auto-generated by Celerity CLI. Do not edit.
const { handler } = require("@celerity-sdk/serverless-aws/handler");
module.exports = { handler };
`

// Generate respects an existing entry file of either variant in stagingDir
// so developers can opt out of the generated bootstrap regardless of the
// project's module system.
func (n *LambdaNodeBootstrap) Generate(stagingDir string) (string, error) {
	filename, content := n.selectTemplate()

	if n.hasExistingEntryFile(stagingDir) {
		return lambdaNodeBootstrapHandler, nil
	}

	target := filepath.Join(stagingDir, filename)
	if err := os.WriteFile(target, []byte(content), 0644); err != nil {
		return "", err
	}
	return lambdaNodeBootstrapHandler, nil
}

func (n *LambdaNodeBootstrap) selectTemplate() (string, string) {
	if isESMProject(n.AppDir) {
		return lambdaNodeESMFilename, lambdaNodeESMBootstrapContent
	}
	return lambdaNodeCJSFilename, lambdaNodeCJSBootstrapContent
}

func (n *LambdaNodeBootstrap) hasExistingEntryFile(stagingDir string) bool {
	for _, name := range []string{lambdaNodeESMFilename, lambdaNodeCJSFilename} {
		if _, err := os.Stat(filepath.Join(stagingDir, name)); err == nil {
			return true
		}
	}
	return false
}
